func (this *Cryptomus) ParseMarket(market any) any {
	//
	//     {
	//         "id": "01JHN5EFT64YC4HR9KCGM5M65D",
	//         "symbol": "POL_USDT",
	//         "baseCurrency": "POL",
	//         "quoteCurrency": "USDT",
	//         "baseMinSize": "1.00000000",
	//         "quoteMinSize": "5.00000000",
	//         "baseMaxSize": "50000.00000000",
	//         "quoteMaxSize": "10000000000.00000000",
	//         "basePrec": "1",
	//         "quotePrec": "4"
	//     }
	//
	var marketId any = this.SafeString(market, "symbol")
	if IsTrue(IsEqual(marketId, nil)) {
		panic(ExchangeError(Add(this.Id, " parseMarket() missing marketId")))
	}
	var parts []string = Split(marketId, "_")
	var baseId any = GetValue(parts, 0)
	var quoteId any = GetValue(parts, 1)
	var base any = this.SafeCurrencyCode(baseId)
	var quote any = this.SafeCurrencyCode(quoteId)
	var fees any = this.SafeDict(this.Fees, "trading")
	return this.SafeMarketStructure(map[string]any{
		"id":             marketId,
		"symbol":         Add(Add(base, "/"), quote),
		"base":           base,
		"quote":          quote,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"active":         true,
		"type":           "spot",
		"subType":        nil,
		"spot":           true,
		"margin":         false,
		"swap":           false,
		"future":         false,
		"option":         false,
		"contract":       false,
		"settle":         nil,
		"settleId":       nil,
		"contractSize":   nil,
		"linear":         nil,
		"inverse":        nil,
		"taker":          this.SafeNumber(fees, "taker"),
		"maker":          this.SafeNumber(fees, "maker"),
		"percentage":     this.SafeBool(fees, "percentage"),
		"tierBased":      nil,
		"feeSide":        this.SafeString(fees, "feeSide"),
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quotePrec"))),
			"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "basePrec"))),
		},
		"limits": map[string]any{
			"amount": map[string]any{
				"min": this.SafeNumber(market, "quoteMinSize"),
				"max": this.SafeNumber(market, "quoteMaxSize"),
			},
			"price": map[string]any{
				"min": this.SafeNumber(market, "baseMinSize"),
				"max": this.SafeNumber(market, "baseMaxSize"),
			},
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"created": nil,
		"info":    market,
	})
}

/**
 * @method
 * @name cryptomus#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://doc.cryptomus.com/personal/market-cap/assets
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Cryptomus) FetchCurrenciesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Cryptomus) fetchCurrenciesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.PublicGetV1ExchangeMarketAssets(params))
	PanicOnError(response)
	//
	//     {
	//         'state': '0',
	//         'result': [
	//             {
	//                 'currency_code': 'USDC',
	//                 'network_code': 'bsc',
	//                 'can_withdraw': true,
	//                 'can_deposit': true,
	//                 'min_withdraw': '1.00000000',
	//                 'max_withdraw': '10000000.00000000',
	//                 'max_deposit': '10000000.00000000',
	//                 'min_deposit': '1.00000000'
	//             },
	//             ...
	//         ]
	//     }
	//
	var coins any = this.SafeList(response, "result")
	var groupedById map[string]any = this.GroupBy(coins, "currency_code")
	var groupedArray []any = ObjectValues(groupedById)

	ch <- this.ParseCurrencies(groupedArray)
	return nil
}
func (this *Cryptomus) ParseCurrency(rawCurrency any) any {
	// currency here is array of networks
	var id any = nil // all entries have same id, as they were grouped by
	var code any = nil
	var networks map[string]any = map[string]any{}
	for i := 0; IsLessThan(i, GetArrayLength(rawCurrency)); i++ {
		var networkEntry any = GetValue(rawCurrency, i)
		// set ID on first loop
		if IsTrue(IsEqual(id, nil)) {
			id = this.SafeString(networkEntry, "currency_code")
			code = this.SafeCurrencyCode(id)
		}
		var networkId any = this.SafeString(networkEntry, "network_code")
		var networkCode any = this.NetworkIdToCode(networkId, code)
		if IsTrue(!IsEqual(networkCode, nil)) {
			AddElementToObject(networks, networkCode, map[string]any{
				"id":      networkId,
				"network": networkCode,
				"limits": map[string]any{
					"withdraw": map[string]any{
						"min": this.SafeNumber(networkEntry, "min_withdraw"),
						"max": this.SafeNumber(networkEntry, "max_withdraw"),
					},
					"deposit": map[string]any{
						"min": this.SafeNumber(networkEntry, "min_deposit"),
						"max": this.SafeNumber(networkEntry, "max_deposit"),
					},
				},
				"active":    nil,
				"deposit":   this.SafeBool(networkEntry, "can_deposit"),
				"withdraw":  this.SafeBool(networkEntry, "can_withdraw"),
				"fee":       nil,
				"precision": nil,
				"info":      networkEntry,
			})
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":       id,
		"code":     code,
		"networks": networks,
		"info":     rawCurrency,
	})
}

/**
 * @method
 * @name cryptomus#fetchTickers
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
 * @see https://doc.cryptomus.com/personal/market-cap/tickers
 * @param {string[]} [symbols] unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Cryptomus) FetchTickersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Cryptomus) fetchTickersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	symbols := GetArg(optionalArgs, 0, nil)
	_ = symbols
	params := GetArg(optionalArgs, 1, map[string]any{})
	_ = params
	if IsTrue(IsEqual(this.Markets, nil)) {

		retRes48912 := (<-this.LoadMarketsAsync())
		PanicOnError(retRes48912)
	}
	symbols = this.MarketSymbols(symbols)

	response := (<-this.PublicGetV1ExchangeMarketTickers(params))
	PanicOnError(response)
	//
	//     {
	//         "data": [
	//         {
	//             "currency_pair": "MATIC_USDT",
	//             "last_price": "0.342",
	//             "base_volume": "1676.84092771",
	//             "quote_volume": "573.48033609043"
	//         },
	//         ...
	//     }
	//
	var data any = this.SafeList(response, "data")

	ch <- this.ParseTickers(data, symbols)
	return nil
}
func (this *Cryptomus) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	//     {
	//         "currency_pair": "XMR_USDT",
	//         "last_price": "158.04829772",
	//         "base_volume": "0.35185785",
	//         "quote_volume": "55.523761128544"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(ticker, "currency_pair")
	market = this.SafeMarket(marketId, market)
	var symbol any = GetValue(market, "symbol")
	var last any = this.SafeString(ticker, "last_price")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     nil,
		"datetime":      nil,
		"high":          nil,
		"low":           nil,
		"bid":           nil,
		"bidVolume":     nil,
		"ask":           nil,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    this.SafeString(ticker, "base_volume"),
		"quoteVolume":   this.SafeString(ticker, "quote_volume"),
		"info":          ticker,
	}, market)
}

