func (this *Cryptomus) ParseOrderStatus(optionalArgs ...any) any {
	status := GetArg(optionalArgs, 0, nil)
	_ = status
	var statuses map[string]any = map[string]any{
		"active":              "open",
		"completed":           "closed",
		"partially_completed": "open",
		"cancelled":           "canceled",
		"expired":             "expired",
		"failed":              "failed",
	}
	return this.SafeString(statuses, status, status)
}

/**
 * @method
 * @name cryptomus#fetchTradingFees
 * @description fetch the trading fees for multiple markets
 * @see https://trade-docs.coinlist.co/?javascript--nodejs#list-fees
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [fee structures]{@link https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
 */
func (this *Cryptomus) FetchTradingFeesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTradingFeesBody(ch, optionalArgs...)
	return ch
}
func (this *Cryptomus) fetchTradingFeesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.PrivateGetV2UserApiExchangeAccountTariffs(params))
	PanicOnError(response)
	//
	//     {
	//         result: {
	//             equivalent_currency_code: 'USD',
	//             current_tariff_step: {
	//                 step: '0',
	//                 from_turnover: '0.00000000',
	//                 maker_percent: '0.08',
	//                 taker_percent: '0.1'
	//             },
	//             tariff_steps: [
	//                 {
	//                     step: '0',
	//                     from_turnover: '0.00000000',
	//                     maker_percent: '0.08',
	//                     taker_percent: '0.1'
	//                 },
	//                 {
	//                     step: '1',
	//                     from_turnover: '100001.00000000',
	//                     maker_percent: '0.06',
	//                     taker_percent: '0.095'
	//                 },
	//                 {
	//                     step: '2',
	//                     from_turnover: '250001.00000000',
	//                     maker_percent: '0.055',
	//                     taker_percent: '0.085'
	//                 },
	//                 {
	//                     step: '3',
	//                     from_turnover: '500001.00000000',
	//                     maker_percent: '0.05',
	//                     taker_percent: '0.075'
	//                 },
	//                 {
	//                     step: '4',
	//                     from_turnover: '2500001.00000000',
	//                     maker_percent: '0.04',
	//                     taker_percent: '0.07'
	//                 }
	//             ],
	//             daily_turnover: '0.00000000',
	//             monthly_turnover: '77.52062617',
	//             circulation_funds: '25.48900443'
	//         }
	//     }
	//
	var data any = this.SafeDict(response, "result", map[string]any{})
	var currentFeeTier any = this.SafeDict(data, "current_tariff_step", map[string]any{})
	var makerFee any = this.SafeString(currentFeeTier, "maker_percent")
	var takerFee any = this.SafeString(currentFeeTier, "taker_percent")
	makerFee = Precise.StringDiv(makerFee, "100")
	takerFee = Precise.StringDiv(takerFee, "100")
	var feeTiers any = this.SafeList(data, "tariff_steps", []any{})
	var result map[string]any = map[string]any{}
	var tiers any = this.ParseFeeTiers(feeTiers)
	var symbols any = this.Symbols
	if IsTrue(IsEqual(symbols, nil)) {

		ch <- result
		return nil
	}
	for i := 0; IsLessThan(i, GetArrayLength(symbols)); i++ {
		var symbol any = GetValue(symbols, i)
		AddElementToObject(result, symbol, map[string]any{
			"info":       response,
			"symbol":     symbol,
			"maker":      this.ParseNumber(makerFee),
			"taker":      this.ParseNumber(takerFee),
			"percentage": true,
			"tierBased":  true,
			"tiers":      tiers,
		})
	}

	ch <- result
	return nil
}
func (this *Cryptomus) ParseFeeTiers(feeTiers any, optionalArgs ...any) any {
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var takerFees any = []any{}
	var makerFees any = []any{}
	for i := 0; IsLessThan(i, GetArrayLength(feeTiers)); i++ {
		var tier any = GetValue(feeTiers, i)
		var turnover any = this.SafeNumber(tier, "from_turnover")
		var taker any = this.SafeString(tier, "taker_percent")
		var maker any = this.SafeString(tier, "maker_percent")
		maker = Precise.StringDiv(maker, "100")
		taker = Precise.StringDiv(taker, "100")
		AppendToArray(&makerFees, []any{turnover, this.ParseNumber(maker)})
		AppendToArray(&takerFees, []any{turnover, this.ParseNumber(taker)})
	}
	return map[string]any{
		"maker": makerFees,
		"taker": takerFees,
	}
}
func (this *Cryptomus) Sign(path any, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	method := GetArg(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var endpoint any = this.ImplodeParams(path, params)
	params = this.Omit(params, this.ExtractParams(path))
	var url any = Add(Add(GetValue(GetValue(this.Urls, "api"), api), "/"), endpoint)
	if IsTrue(IsEqual(api, "private")) {
		this.CheckRequiredCredentials()
		var jsonParams any = ""
		headers = map[string]any{
			"userId": this.Uid,
		}
		if IsTrue(!IsEqual(method, "GET")) {
			body = this.Json(params)
			jsonParams = body
			AddElementToObject(headers, "Content-Type", "application/json")
		} else {
			var query string = this.Urlencode(params)
			if IsTrue(!IsEqual(GetLength(query), 0)) {
				url = Add(url, Add("?", query))
			}
		}
		var jsonParamsBase64 string = this.StringToBase64(jsonParams)
		var stringToSign any = Add(jsonParamsBase64, this.Secret)
		var signature any = this.Hash(this.Encode(stringToSign), md5)
		AddElementToObject(headers, "sign", signature)
	} else {
		var query string = this.Urlencode(params)
		if IsTrue(!IsEqual(GetLength(query), 0)) {
			url = Add(url, Add("?", query))
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}
func (this *Cryptomus) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsTrue(IsEqual(response, nil)) {
		return nil
	}
	if IsTrue(InOp(response, "code")) {
		var code any = this.SafeString(response, "code")
		var feedback any = Add(Add(this.Id, " "), body)
		this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), code, feedback)
		panic(ExchangeError(feedback))
	} else if IsTrue(InOp(response, "message")) {
		//
		//      {"message":"Minimum amount 15 USDT","state":1}
		//
		var message any = this.SafeString(response, "message")
		var feedback any = Add(Add(this.Id, " "), body)
		this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), message, feedback)
		this.ThrowBroadlyMatchedException(GetValue(this.Exceptions, "broad"), message, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewCryptomus(userConfig map[string]any) *Cryptomus {
	p := newCryptomus()
	p.Init(userConfig)
	return p
}

func (this *Cryptomus) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

